    // ---- inlined src/client/state.js ----
/**
 * Client state: the node cache, the revision protocol that keeps it convergent,
 * the transport to the plugin's own host routes, and the device-local memory of
 * how the board was left.
 *
 * The revision rules are codeg-plus's `canvas-store.ts`, ported unchanged:
 *   - the event stream is the ONLY channel that advances `revision`;
 *   - `<= revision` is stale (drop), `== revision + 1` applies, `> revision + 1`
 *     is a gap — drop it and refetch the whole snapshot;
 *   - a mutation RESPONSE never advances the revision. Its value is applied as an
 *     optimistic confirmation only while its own revision is still ahead, so both
 *     arrival orders converge and no own-origin special case is needed.
 *
 * @module dsh-plugin-canvas/client/state
 */
const PLUGIN_ID = 'dsh-plugin-canvas'
const ROUTE_PREFIX = '/dsh-plugin-canvas'
const SSE_PATH = '/dsh-plugin-canvas/events'

/** Device-local keys. Advisory, never authoritative — the ledger is the board. */
const KEY_VIEWPORT = 'dsh-plugin-canvas:viewport'
const KEY_EXPANDED_CARDS = 'dsh-plugin-canvas:expanded-cards'
const KEY_EXPANDED_REGIONS = 'dsh-plugin-canvas:expanded-regions'
const KEY_MINIMAP = 'dsh-plugin-canvas:minimap'

const model = {
  open: false,
  revision: 0,
  hydrated: false,
  /** ledger id → node row. Replaced, never mutated, on every apply. */
  nodes: new Map(),
  sessions: [],
  workspaces: [],
  agents: [],
  /** Element ids (`node-<id>` / `member-<id>-<sessionId>`). */
  selected: new Set(),
  expandedRegions: new Set(),
  detailCards: new Set(),
  transcripts: new Map(),
  viewport: { x: 0, y: 0, zoom: 1 },
  /** A viewport came back from storage, so the first open must not re-fit. */
  restoredViewport: false,
  minimap: true,
  /** Transient interaction state — never persisted, never sent. */
  overlay: new Map(),
  sizeOverlay: new Map(),
  frozenMembers: null,
  dropHint: null,
  dropTargetRegionId: null,
  guides: [],
  marquee: null,
  renaming: null,
  editingNote: null,
  connected: false,
  toasts: [],
}

const listeners = new Set()

function subscribe(fn) {
  listeners.add(fn)
  return () => listeners.delete(fn)
}

function emit() {
  for (const fn of [...listeners]) {
    try {
      fn()
    } catch (error) {
      console.warn('[dsh-plugin-canvas] listener threw:', error?.message ?? error)
    }
  }
}

function toast(message) {
  const entry = { id: `${Date.now()}-${Math.random()}`, message: String(message) }
  model.toasts = [...model.toasts, entry]
  emit()
  setTimeout(() => {
    model.toasts = model.toasts.filter((t) => t.id !== entry.id)
    emit()
  }, 4200)
}

function readJson(key) {
  try {
    const raw = window.localStorage.getItem(key)
    return raw === null ? null : JSON.parse(raw)
  } catch {
    return null
  }
}

function writeJson(key, value) {
  try {
    window.localStorage.setItem(key, JSON.stringify(value))
  } catch {
    /* quota or a private-mode denial is not worth a broken board */
  }
}

/** Restore the device-local view state. Every entry degrades harmlessly: an id
 *  that no longer matches a row simply opens nothing. */
function loadViewState() {
  const viewport = readJson(KEY_VIEWPORT)
  if (
    viewport !== null &&
    Number.isFinite(viewport.x) &&
    Number.isFinite(viewport.y) &&
    Number.isFinite(viewport.zoom)
  ) {
    model.viewport = { x: viewport.x, y: viewport.y, zoom: clampZoom(viewport.zoom) }
    model.restoredViewport = true
  }
  for (const id of readJson(KEY_EXPANDED_CARDS) ?? []) {
    if (Number.isInteger(id)) model.detailCards.add(id)
  }
  for (const id of readJson(KEY_EXPANDED_REGIONS) ?? []) {
    if (Number.isInteger(id)) model.expandedRegions.add(id)
  }
  // Anything but a literal `false` means shown: the map is how a board bigger
  // than the window stays comprehensible, so only an explicit dismissal sticks.
  model.minimap = readJson(KEY_MINIMAP) !== false
}

function saveViewport() {
  writeJson(KEY_VIEWPORT, model.viewport)
}

function saveExpanded() {
  writeJson(KEY_EXPANDED_CARDS, [...model.detailCards])
  writeJson(KEY_EXPANDED_REGIONS, [...model.expandedRegions])
}

function saveMinimap() {
  writeJson(KEY_MINIMAP, model.minimap)
}

// ── transport ──

/** One JSON call to the plugin's own host route. Throws with the server's own
 *  message so every caller can just toast it. */
async function api(path, body) {
  const response = await fetch(`${ROUTE_PREFIX}${path}`, {
    method: body === undefined ? 'GET' : 'POST',
    headers: body === undefined ? undefined : { 'content-type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  })
  let payload
  try {
    payload = await response.json()
  } catch {
    throw new Error(`HTTP ${response.status}`)
  }
  if (payload?.ok !== true) {
    throw new Error(payload?.error?.message ?? `HTTP ${response.status}`)
  }
  return payload.value
}

/** Apply one committed change to the node cache. Every payload is full-state and
 *  idempotent, so our own mutations and everyone else's follow one path. */
function applyTo(nodes, change) {
  switch (change.kind) {
    case 'upsert':
      nodes.set(change.node.id, change.node)
      break
    case 'moved':
      for (const move of change.moves) {
        const existing = nodes.get(move.id)
        if (existing !== undefined) nodes.set(move.id, { ...existing, x: move.x, y: move.y })
      }
      break
    case 'deleted':
      nodes.delete(change.id)
      break
    case 'detached': {
      // One transaction on the host: the membership removal plus the new pin. The
      // region's new member list is not in the payload, so scrub it here — a
      // filter is idempotent, matching the event contract.
      const sessionId = change.node.sessionId
      if (change.removedFrom !== null && sessionId != null) {
        const region = nodes.get(change.removedFrom)
        if (region !== undefined) {
          nodes.set(change.removedFrom, {
            ...region,
            memberIds: region.memberIds.filter((m) => m !== sessionId),
          })
        }
      }
      nodes.set(change.node.id, change.node)
      break
    }
    case 'grouped':
      // Delete before insert: the absorbed pins and the region that swallowed
      // them committed together. Both halves are idempotent.
      for (const id of change.deletedIds) nodes.delete(id)
      nodes.set(change.node.id, change.node)
      break
    case 'pruned':
      for (const id of change.deletedIds) nodes.delete(id)
      for (const node of change.updated) nodes.set(node.id, node)
      break
  }
}

let gapHighWater = 0
let refetchInFlight = null

/** Handle one streamed change. */
function handleChange(change) {
  if (!Number.isFinite(change?.revision)) return
  if (change.revision <= model.revision) return
  if (change.revision > model.revision + 1) {
    // A gap: some event was lost. The change is NOT applied — a payload is only
    // coherent against its exact predecessor state — and the snapshot repairs
    // everything at once.
    gapHighWater = Math.max(gapHighWater, change.revision)
    void refetchState()
    return
  }
  const nodes = new Map(model.nodes)
  applyTo(nodes, change)
  model.nodes = nodes
  model.revision = change.revision
  pruneViewState()
  emit()
}

/** Apply a mutation response, but only while its own event is still on its way. */
function applyResponse(revision, mutate) {
  if (!Number.isFinite(revision) || revision <= model.revision) return
  const nodes = new Map(model.nodes)
  mutate(nodes)
  model.nodes = nodes
  pruneViewState()
  emit()
}

/** Drop view state pointing at rows the board no longer has. */
function pruneViewState() {
  let dirty = false
  for (const id of [...model.detailCards]) {
    if (!model.nodes.has(id)) {
      model.detailCards.delete(id)
      dirty = true
    }
  }
  for (const id of [...model.expandedRegions]) {
    if (!model.nodes.has(id)) {
      model.expandedRegions.delete(id)
      dirty = true
    }
  }
  if (dirty) saveExpanded()
}

/** Fetch a fresh snapshot (initial hydrate, gap repair, stream reconnect).
 *  Coalesces: at most one in flight, callers share its outcome. */
function refetchState() {
  if (refetchInFlight !== null) return refetchInFlight
  refetchInFlight = api('/state')
    .then((snapshot) => {
      refetchInFlight = null
      // The ledger response is also where the language comes from — the browser
      // half cannot see the shell's environment. Adopted before the emit below, so
      // nothing has painted in the wrong language yet.
      setLanguage(snapshot?.language)
      if (!Number.isFinite(snapshot?.revision)) return
      const before = model.revision
      // A snapshot read BEFORE a mutation we already applied has not repaired
      // anything — accept nothing.
      if (snapshot.revision >= before) {
        model.nodes = new Map(snapshot.nodes.map((n) => [n.id, n]))
        model.revision = snapshot.revision
        model.hydrated = true
        pruneViewState()
        emit()
      }
      // Still behind a gap we saw, but only worth another round if THIS one made
      // progress. Chaining on a snapshot that reported the same revision would
      // spin until the host happens to commit something — the missing mutation
      // arrives as an event anyway, and its own gap check re-triggers this.
      if (gapHighWater > model.revision && model.revision > before) void refetchState()
    })
    .catch((error) => {
      refetchInFlight = null
      console.warn('[dsh-plugin-canvas] snapshot fetch failed:', error?.message ?? error)
      setTimeout(() => {
        // Quiet-board self-heal: no later event may ever re-trigger this.
        if (model.open) void refetchState()
      }, 3000)
    })
  return refetchInFlight
}

/** Refresh the workspace / session / agent view. */
async function refetchSessions(force = false) {
  try {
    const value = await api(`/sessions${force ? '?refresh=1' : ''}`)
    model.sessions = value.sessions ?? []
    model.workspaces = value.workspaces ?? []
    model.agents = value.agents ?? []
    emit()
  } catch (error) {
    console.warn('[dsh-plugin-canvas] session view failed:', error?.message ?? error)
  }
}

let stream = null

function startStream() {
  if (stream !== null || typeof window.EventSource !== 'function') return
  const source = new window.EventSource(SSE_PATH)
  stream = source
  source.addEventListener('open', () => {
    model.connected = true
    emit()
  })
  source.addEventListener('hello', () => {
    model.connected = true
    // The baseline frame only reports where the host is; the snapshot is what
    // reconciles, and a reconnect may have missed events either way.
    void refetchState()
    emit()
  })
  source.addEventListener('change', (event) => {
    try {
      handleChange(JSON.parse(event.data))
    } catch (error) {
      console.warn('[dsh-plugin-canvas] bad change frame:', error?.message ?? error)
    }
  })
  source.addEventListener('error', () => {
    // EventSource reconnects on its own; only the badge changes.
    model.connected = false
    emit()
  })
}

function stopStream() {
  if (stream === null) return
  try {
    stream.close()
  } catch {
    /* already closed */
  }
  stream = null
  model.connected = false
}

    // ---- inlined src/client/viewport.js ----
/**
 * Viewport math: board ↔ screen conversion, zooming about a point, fit-view, the
 * dot lattice, and the navigator map.
 *
 * The board layer is one `transform: translate(x, y) scale(z)` with a `0 0`
 * origin, so a board coordinate maps to a screen coordinate by `p * z + offset`
 * and back by `(s - offset) / z`. Every gesture converts through these two
 * functions rather than doing its own arithmetic — a drag that used a slightly
 * different formula than the renderer is exactly how a card ends up lagging the
 * pointer at zooms other than 100%.
 *
 * @module dsh-plugin-canvas/client/viewport
 */

/** Zoom step for the corner buttons, and the animation-free duration budget. */
const ZOOM_STEP = 1.2
const VIEWPORT_SAVE_DELAY_MS = 500

let saveTimer = null

/** Persist the viewport on a trailing debounce: a pan emits one frame per mouse
 *  move, and localStorage is synchronous. */
function scheduleViewportSave() {
  if (saveTimer !== null) clearTimeout(saveTimer)
  saveTimer = setTimeout(() => {
    saveTimer = null
    saveViewport()
  }, VIEWPORT_SAVE_DELAY_MS)
}

function flushViewportSave() {
  if (saveTimer === null) return
  clearTimeout(saveTimer)
  saveTimer = null
  saveViewport()
}

/** Screen point (client coords) → board point. */
function screenToBoard(rect, clientX, clientY) {
  const { x, y, zoom } = model.viewport
  return { x: (clientX - rect.left - x) / zoom, y: (clientY - rect.top - y) / zoom }
}

/** Board point → screen point, relative to the surface's top-left. */
function boardToScreen(point) {
  const { x, y, zoom } = model.viewport
  return { x: point.x * zoom + x, y: point.y * zoom + y }
}

/** Screen distance → board distance. */
function toBoardDistance(px) {
  return px / model.viewport.zoom
}

/** Replace the viewport, clamping the zoom. */
function setViewport(next) {
  model.viewport = {
    x: Number.isFinite(next.x) ? next.x : model.viewport.x,
    y: Number.isFinite(next.y) ? next.y : model.viewport.y,
    zoom: clampZoom(next.zoom ?? model.viewport.zoom),
  }
  scheduleViewportSave()
  emit()
}

/** Zoom keeping one screen point fixed — the only zoom that feels attached to
 *  the pointer. */
function zoomAbout(rect, clientX, clientY, factor) {
  const before = model.viewport
  const zoom = clampZoom(before.zoom * factor)
  if (zoom === before.zoom) return
  const sx = clientX - rect.left
  const sy = clientY - rect.top
  // Solve for the offset that keeps (sx, sy) over the same board point.
  setViewport({
    x: sx - ((sx - before.x) / before.zoom) * zoom,
    y: sy - ((sy - before.y) / before.zoom) * zoom,
    zoom,
  })
}

/** Zoom about the surface centre (the corner buttons). */
function zoomByStep(rect, direction) {
  zoomAbout(rect, rect.left + rect.width / 2, rect.top + rect.height / 2, direction > 0 ? ZOOM_STEP : 1 / ZOOM_STEP)
}

/** Jump to exactly 100%, about the centre. */
function resetZoom(rect) {
  const before = model.viewport
  if (before.zoom === 1) return
  const sx = rect.width / 2
  const sy = rect.height / 2
  setViewport({
    x: sx - ((sx - before.x) / before.zoom) * 1,
    y: sy - ((sy - before.y) / before.zoom) * 1,
    zoom: 1,
  })
}

/** Union of every rendered element's box, in board units. */
function boardBounds(elements) {
  if (elements.length === 0) return null
  let minX = Infinity
  let minY = Infinity
  let maxX = -Infinity
  let maxY = -Infinity
  for (const el of elements) {
    minX = Math.min(minX, el.position.x)
    minY = Math.min(minY, el.position.y)
    maxX = Math.max(maxX, el.position.x + el.width)
    maxY = Math.max(maxY, el.position.y + el.height)
  }
  return { x: minX, y: minY, width: maxX - minX, height: maxY - minY }
}

/**
 * Fit every element into view. `padding` is a fraction of the viewport (0.2 like
 * codeg-plus), and `maxZoom` caps the scale so a board holding one note doesn't
 * blow it up to fill the window.
 */
function fitView(rect, elements, options = {}) {
  const bounds = boardBounds(elements)
  if (bounds === null || rect.width === 0 || rect.height === 0) return
  const padding = options.padding ?? 0.2
  const maxZoom = options.maxZoom ?? 1
  const usableW = rect.width * (1 - padding)
  const usableH = rect.height * (1 - padding)
  const zoom = clampZoom(
    Math.min(maxZoom, Math.min(usableW / Math.max(bounds.width, 1), usableH / Math.max(bounds.height, 1)))
  )
  setViewport({
    x: rect.width / 2 - (bounds.x + bounds.width / 2) * zoom,
    y: rect.height / 2 - (bounds.y + bounds.height / 2) * zoom,
    zoom,
  })
}

/** Push the viewport onto the DOM: the board transform and the dot lattice the
 *  drag snapping lands on. */
function applyViewport(surfaceEl, boardEl) {
  const { x, y, zoom } = model.viewport
  boardEl.style.transform = `translate(${x}px, ${y}px) scale(${zoom})`
  const gap = BOARD_DOT_GAP * zoom
  surfaceEl.style.backgroundImage =
    'radial-gradient(circle, var(--dshc-dot) 1px, transparent 1px)'
  surfaceEl.style.backgroundSize = `${gap}px ${gap}px`
  // The gradient centres its dot in each tile, so the tile origin has to sit half
  // a gap BEFORE the board coordinate the dot belongs to. Without the shift the
  // painted dots land halfway between the lattice positions drags snap to — the
  // one invariant board units exist to keep (see units.js).
  surfaceEl.style.backgroundPosition = `${(x % gap) - gap / 2}px ${(y % gap) - gap / 2}px`
}

/** Map size, and how much board it pads around the content. */
const MAP_WIDTH = 168
const MAP_HEIGHT = 126

/**
 * Paint the navigator map: every element as a block, plus the current viewport
 * frame. Clicking or dragging inside it re-centres the board — the map is how a
 * board bigger than the window stays navigable.
 */
function renderMinimap(mapEl, elements, rect) {
  mapEl.style.width = `${MAP_WIDTH}px`
  mapEl.style.height = `${MAP_HEIGHT}px`
  const { x, y, zoom } = model.viewport
  const view = { x: -x / zoom, y: -y / zoom, width: rect.width / zoom, height: rect.height / zoom }
  const content = boardBounds(elements) ?? { x: 0, y: 0, width: 1, height: 1 }
  // The map must show both the content and where you are, or panning off the
  // content would leave the frame stuck against an edge with no way to read it.
  const minX = Math.min(content.x, view.x)
  const minY = Math.min(content.y, view.y)
  const maxX = Math.max(content.x + content.width, view.x + view.width)
  const maxY = Math.max(content.y + content.height, view.y + view.height)
  const span = { x: minX, y: minY, width: Math.max(maxX - minX, 1), height: Math.max(maxY - minY, 1) }
  const scale = Math.min(MAP_WIDTH / span.width, MAP_HEIGHT / span.height)
  const offsetX = (MAP_WIDTH - span.width * scale) / 2
  const offsetY = (MAP_HEIGHT - span.height * scale) / 2
  const place = (el, box, kind) => {
    el.style.left = `${offsetX + (box.x - span.x) * scale}px`
    el.style.top = `${offsetY + (box.y - span.y) * scale}px`
    el.style.width = `${Math.max(box.width * scale, 2)}px`
    el.style.height = `${Math.max(box.height * scale, 2)}px`
    if (kind !== undefined) el.dataset.kind = kind
  }
  mapEl.textContent = ''
  for (const element of elements) {
    if (element.type === 'sessionCard' && element.regionId !== undefined) continue
    const block = document.createElement('div')
    block.className = 'dshc-map-node'
    place(block, { ...element.position, width: element.width, height: element.height }, element.type)
    mapEl.append(block)
  }
  const frame = document.createElement('div')
  frame.className = 'dshc-map-view'
  place(frame, view)
  mapEl.append(frame)
  mapEl._span = span
  mapEl._scale = scale
  mapEl._offset = { x: offsetX, y: offsetY }
}

/** Board point under a click on the map, or null when it has not been painted. */
function minimapToBoard(mapEl, clientX, clientY) {
  if (mapEl._span === undefined) return null
  const box = mapEl.getBoundingClientRect()
  return {
    x: mapEl._span.x + (clientX - box.left - mapEl._offset.x) / mapEl._scale,
    y: mapEl._span.y + (clientY - box.top - mapEl._offset.y) / mapEl._scale,
  }
}

/** Centre the viewport on one board point. */
function centerOn(rect, point) {
  const { zoom } = model.viewport
  setViewport({ x: rect.width / 2 - point.x * zoom, y: rect.height / 2 - point.y * zoom, zoom })
}

